import { computed, ref, watch } from '../src/index'

test('tmp computed sync watcher order', () => {
  const n = ref(0)
  const c = computed(() => n.value)
  const calls: number[] = []
  for (let i = 0; i < 5; i++) {
    watch(
      c,
      () => {
        calls.push(i)
      },
      { flush: 'sync' },
    )
  }
  n.value++
  expect(calls).toEqual([0, 1, 2, 3, 4])
})

